29: /// Estimate the run's cost, write the durable ledger rows and emit a
30: /// `BudgetAlert` when a scope crossed its threshold.
31: ///
32: /// Returns the estimated cost, or `None` when cost tracking is disabled or the
33: /// model is unpriced. Ledger writes are fire-and-forget so the hot path never
34: /// blocks on a database write. The caller emits the terminal event afterwards,
35: /// so a `BudgetAlert` always precedes it.
36: pub async fn settle_run_cost(
37:     inputs: RunCostInputs<'_>,
38:     cost_budget: &CostBudgetTracker,
39:     persistence: Option<&Arc<dyn PersistenceLayer>>,
40:     sink: &dyn RuntimeEventSink,
41: ) -> Option<f64> {
42:     let cost = if inputs.cost_tracking_enabled {
43:         crate::llm::catalog::estimate_cost(
44:             inputs.model,
45:             u64::from(inputs.input_tokens),
46:             u64::from(inputs.output_tokens),
47:             u64::from(inputs.cache_read_tokens),
48:         )
49:     } else {
50:         None
51:     }?;
52:     let (provider, model_id) = inputs.model.split_once('/')?;
53:     crate::uar::telemetry::metrics::record_llm_cost(provider, model_id, cost);
54: 
55:     // Driver wrappers already charged every model call. Surface a `BudgetAlert`
56:     // for the first scope (in priority order) that crosses its configured
57:     // threshold. Unconfigured scopes have an unlimited `BudgetLimit::default()`,
58:     // so reading the status does not charge the final request again.
59:     // `BudgetScope::Task` is intentionally omitted: this runtime has no task
60:     // entity distinct from a run.
61:     let scopes: [(BudgetScope, &str); 4] = [
62:         (BudgetScope::Run, inputs.run_id),
63:         (BudgetScope::Session, inputs.session_id),
64:         (BudgetScope::Agent, inputs.agent_id),
65:         (BudgetScope::Global, "global"),
66:     ];
67:     let mut alert: Option<(BudgetScope, String, f64, f64, bool)> = None;
68:     for (scope, scope_id) in scopes {
69:         let status = cost_budget.status(scope, scope_id).await;
70:         if let Some(db) = persistence.cloned() {
71:             let scope_str = scope.as_str().to_string();
72:             let scope_id_owned = scope_id.to_string();
73:             tokio::spawn(async move {
74:                 if let Err(e) = db
75:                     .record_cost_entry(&scope_str, &scope_id_owned, cost)
76:                     .await
77:                 {
78:                     tracing::warn!(error = %e, scope = %scope_str, "Failed to persist cost ledger entry");
79:                 }
80:             });
81:         }
82:         if alert.is_none()
83:             && let BudgetStatus::Warning {
84:                 spent_usd,
85:                 limit_usd,
86:             }
87:             | BudgetStatus::Exceeded {
88:                 spent_usd,
89:                 limit_usd,
90:             } = status
91:         {
92:             alert = Some((
93:                 scope,
94:                 scope_id.to_string(),
95:                 spent_usd,
96:                 limit_usd,
97:                 status.is_exceeded(),
98:             ));
99:         }
100:     }
101:     if let Some((scope, scope_id, spent_usd, limit_usd, exceeded)) = alert {
102:         sink.emit(NormalizedEvent::BudgetAlert {
103:             run_id: inputs.run_id.to_string(),
104:             scope: scope.as_str().to_string(),
105:             scope_id,
106:             spent_usd,
107:             limit_usd,
108:             exceeded,
109:         })
110:         .await;
111:     }
112:     Some(cost)
113: }

