37:             let pending = lane.pending.lock().map_err(|_| anyhow::anyhow!("Approval request unavailable"))?;
38:             let Some(request) = pending.as_ref() else { return Ok(None); };
39:             if lane.cancellation.is_cancelled() || request.caller_cancellation.is_cancelled() || request.reply.is_closed() || request.record.expires_at <= Utc::now() ||
40:                 !approval_id.map_or(request.legacy_root_request, |id| id == request.snapshot.approval_id) {
