50:                 .find(|current| current.storage_key() == record.storage_key()) { lane.publish_record(&current).await; }
51:             return Ok(None);
52:         }
53:         let delivered = {
54:             let mut pending = lane.pending.lock().map_err(|_| anyhow::anyhow!("Approval request unavailable"))?;
55:             if pending.as_ref().is_some_and(|request| request.snapshot.approval_id == record.challenge_id) {
56:                 pending.take().is_some_and(|request| !lane.cancellation.is_cancelled() && !request.caller_cancellation.is_cancelled() && request.record.expires_at > Utc::now() && request.reply.send(approved).is_ok())
