43: /// Validate mapping against the protected envelope, never against caller JSON.
44: pub(crate) fn protected_call(record: &ApprovalRecord, envelope: &CheckpointResumeEnvelope) -> anyhow::Result<ApprovalCheckpoint> {
45:     envelope.validate()?;
46:     envelope.require_restorable_execution()?;
47:     let continuation = record.continuation.as_ref().ok_or(CheckpointResumeError::Invalid)?;
48:     let state = envelope.checkpoint()?.try_restore_state()?;
49:     let marker: ApprovalCheckpoint = serde_json::from_value(state.data.get(PENDING_APPROVAL_KEY)
50:         .cloned().ok_or(CheckpointResumeError::Invalid)?)?;
51:     if marker.schema_version != 1 || record.owner_key != envelope.owner_key
52:         || record.root_run_id != envelope.source_run_id || continuation.checkpoint_id != envelope.checkpoint_id
53:         || continuation.checkpoint_revision != envelope.checkpoint_revision
54:         || marker.challenge_id != record.challenge_id || marker.binding_digest != continuation.binding_digest
55:         || marker.call_index != continuation.call_index || marker.call.id != record.tool_call_id
56:         || marker.call.function.name != record.tool_name
57:     { return Err(CheckpointResumeError::Invalid.into()); }
58:     let history = crate::uar::runtime::checkpoint::history_from_checkpoint(&envelope.checkpoint()?)?;
59:     let calls = history.iter().flat_map(|message| message.tool_calls.iter().flatten())
60:         .filter(|call| call.id == marker.call.id).collect::<Vec<_>>();
61:     if calls.len() != 1 || serde_json::to_value(calls[0])? != serde_json::to_value(&marker.call)?
62:         || history.iter().any(|message| message.tool_call_id.as_deref() == Some(marker.call.id.as_str()))
63:     { return Err(CheckpointResumeError::Invalid.into()); }
64:     Ok(marker)
65: }
